/* Code VBA de la macro SolidWorks (version publique caviardée de macro-mise-en-plan/macro-publique.bas),
   affiché par le bouton « Source » de sa fenêtre. */
window.VBA_SOURCES = {"MacroMiseEnPlan": "Option Explicit\n\n'=========================================================================\n' MISE EN PLAN AUTOMATIQUE D'UN ASSEMBLAGE - macro SolidWorks (VBA)\n'\n' Version publique : chemins, noms de projets et conventions internes\n' remplaces par [caviardé].\n'\n' A lancer sur un assemblage ouvert et enregistre. La macro :\n'   1. cree la mise en plan depuis le gabarit (feuilles 001/002/003/Info) ;\n'   2. feuille 001 : deux vues isometriques, une de chaque cote du modele ;\n'   3. feuille 002 : vue de face et vue de cote ;\n'   4. feuille 003 : vue isometrique, une couleur par sous-ensemble ;\n'   5. pour chaque sous-ensemble (\"Unit\") de premier niveau : une feuille\n'      avec sa vue isometrique et sa nomenclature, puis une feuille\n'      face / cote / dessus pour la cotation ;\n'   6. remet les feuilles dans l'ordre et les fait defiler a l'ecran.\n'\n' Chaque vue est orientee par rotations exactes a partir de la vue de face\n' (35,264 deg pour l'isometrique), mise a l'echelle de sa zone et\n' positionnee d'apres son encombrement reel (IView.GetOutline).\n'\n' Reste manuel : cotes, bulles, et la case \"Liste detaillee des pieces\n' soudees\" de la nomenclature (non pilotable par l'API).\n'\n' Developpee avec un assistant IA (Claude) : les notes de travail du projet\n' sont dans CLAUDE.md, cite dans les commentaires.\n'\n' Necessite la reference \"SOLIDWORKS 20XX Type Library\"\n' (Outils > References dans l'editeur VBA).\n'=========================================================================\n\nConst CHEMIN_GABARIT As String = \"[caviardé]\\Mise en plan.drwdot\" ' chemin [caviardé] - MAJ 2026-09-21 : ancien gabarit remplace par le gabarit reellement utilise en production (identifie par comparaison avec une mise en plan de reference) - NON ENCORE VERIFIE que ce fichier contient bien les feuilles 001/002/003/Info dont toute la Phase 1 depend (ActivateSheet echouera avec un message clair si absent).\nConst NOM_FORMAT_FEUILLE As String = \"[caviardé]\\Fond de plan A3.slddrt\" ' chemin [caviardé] - format des feuilles 001/002/003/Info - utilise pour les feuilles Unit crees via NewSheet3 - MAJ 2026-09-21\nConst LARGEUR_FEUILLE As Double = 0.42   ' A3 paysage, metres - confirme par enregistrement\nConst HAUTEUR_FEUILLE As Double = 0.297\nConst SW_COMMAND_NORMAL_TO As Long = 169 ' swCommands_NormalTo (swCommands_e) - \"Normal a\" est une commande de menu, pas une methode API\nConst SW_VIEW_ISOMETRIC As Long = 7      ' swStandardViews_e.swISOMETRIC - confirme fonctionnel\nConst SW_TABLEANCHOR_HAUT_DROIT As Long = 2 ' TableAnnotation.AnchorType - AUCUNE enum nommee trouvee dans l'Explorateur d'objets (recherche \"TableAnchor\" infructueuse, seulement les proprietes Anchored/AnchorType elles-memes) - valeur obtenue le 2026-09-21 en LISANT AnchorType sur une table positionnee \"Haut droit\" a la main (SCRIPTS_VBA/EXPLORATION/LireAncrageTable.bas), pas par recherche du nom d'enum\nConst DELAI_ANIMATION As Single = 0.8    ' secondes - confirme suffisant le 2026-09-20 (0.4 ne l'etait pas)\nConst DELAI_PARCOURS_FEUILLES As Single = 0.4 ' secondes - pause entre deux feuilles lors du parcours visuel de fin de generation (cf. plus bas) - purement cosmetique (video de demonstration), premiere estimation A AJUSTER VISUELLEMENT selon le rendu souhaite (plus court = plus rapide, plus long = plus lisible a l'ecran).\nConst PI As Double = 3.14159265358979\nConst ANGLE_ISO As Double = 35.264389682754 ' arctan(1/racine(2)), en degres\nConst CHEMIN_GABARIT_NOMENCLATURE As String = \"[caviardé]\\Nomenclature.sldbomtbt\" ' chemin [caviardé] - MAJ 2026-09-21 : ancien gabarit remplace par celui reellement utilise en production (identifie par comparaison avec une mise en plan de reference) - le tri Profiles-en-premier vu sur la reference est probablement un reglage DEJA PRESENT dans ce fichier (onglet Trier des proprietes de table), a verifier apres 1er test plutot qu'a coder\nConst MARGE_VUE As Double = 0.02 ' metres - espace laisse entre deux vues/tables placees dynamiquement via GetOutline\nConst MARGE_CARTOUCHE As Double = 0.01 ' metres - entre le cadre/cartouche du gabarit et le 1er element (vue ou nomenclature) - distincte de MARGE_VUE (entre deux vues). Premiere estimation, resserree par rapport a MARGE_VUE car le cadre du gabarit est proche du bord papier - A AJUSTER VISUELLEMENT (meme demarche que DELAI_ANIMATION).\nConst MARGE_CARTOUCHE_UNIT As Double = 0.03 ' metres - comme MARGE_CARTOUCHE, mais pour le HAUT des feuilles Unit (0N0/0N1) uniquement : ces feuilles affichent en plus le libelle \"Unit A\"/\"Unit B\" (lie a $PRP:\"Désignation Secondaire\", cf. CLAUDE.md) juste sous le cartouche superieur, un bandeau que les feuilles 001/002/003 n'ont pas - constate visuellement le 2026-10-12 (vues ISO/Face/Cote Unit chevauchant ce libelle avec la seule MARGE_CARTOUCHE). Premiere estimation, A AJUSTER VISUELLEMENT.\nConst HAUTEUR_ZONE_VUES As Double = 0.22 ' metres - hauteur utilisable pour les vues sur une feuille A3 paysage, sous le bandeau haut et au dessus du cartouche bas - estimation initiale, A AJUSTER VISUELLEMENT.\nConst LARGEUR_ZONE_NOMENCLATURE As Double = 0.12 ' metres - largeur reservee a la nomenclature (coin haut-droit) sur la feuille ISO+BOM d'une Unit, pour calculer la largeur cible restante pour la vue ISO.\n\nSub GenererVuesGlobales()\n\n    Dim swApp As SldWorks.SldWorks\n    Set swApp = Application.SldWorks\n\n    Dim swAssy As SldWorks.ModelDoc2\n    Set swAssy = swApp.ActiveDoc\n\n    If swAssy Is Nothing Or swAssy.GetType <> 2 Then ' 2 = swDocASSEMBLY\n        MsgBox \"Ouvrez l'assemblage racine a mettre en plan.\", vbExclamation\n        Exit Sub\n    End If\n\n    Dim assyPath As String\n    assyPath = swAssy.GetPathName\n    If assyPath = \"\" Then\n        MsgBox \"Enregistrez l'assemblage avant de lancer la generation (chemin vide).\", vbExclamation\n        Exit Sub\n    End If\n\n    Dim swMathUtil As SldWorks.MathUtility\n    Set swMathUtil = swApp.GetMathUtility\n\n    ' --- 1. Creer le document de mise en plan depuis le gabarit ---\n    Dim swDraw As SldWorks.ModelDoc2\n    Set swDraw = swApp.NewDocument(CHEMIN_GABARIT, 12, LARGEUR_FEUILLE, HAUTEUR_FEUILLE)\n    If swDraw Is Nothing Then\n        MsgBox \"Echec de creation du document (NewDocument a renvoye Nothing). Verifiez le chemin du gabarit :\" & vbCrLf & CHEMIN_GABARIT, vbCritical\n        Exit Sub\n    End If\n\n    Dim swView As Object\n    Dim errTxt As String\n    Dim rapport As String\n    Dim echelleDiag As String ' diagnostic d'AjusterEchelleVue - affiche dans le rapport seulement en cas d'erreur (garde le rapport court sinon)\n\n    ' --- 2. Feuille 001 : Iso haut-gauche + Iso haut-droite (2 cotes differents, meme inclinaison) ---\n    If Not swDraw.ActivateSheet(\"001\") Then\n        MsgBox \"Feuille '001' introuvable dans le gabarit. Verifiez le nom exact des feuilles.\", vbCritical\n        Exit Sub\n    End If\n\n    ' Phase 1 (001/002/003) : deja validee de bout en bout, rapport reduit a\n    ' une ligne par vue (plus le detail complet - voir historique si besoin)\n    ' pour laisser la place a la Phase 2 dans la boite de dialogue finale.\n    ' Zone cible pour 2 vues cote a cote, collees au coin haut-gauche utile\n    ' de la feuille (MARGE_CARTOUCHE, pas le bord papier brut) : chacune a\n    ' droit a la moitie de la largeur utile, moins la marge entre les deux.\n    Dim largeurZone2 As Double\n    largeurZone2 = (LARGEUR_FEUILLE - 2# * MARGE_CARTOUCHE - MARGE_VUE) / 2#\n\n    Dim swVues001 As New Collection\n\n    CreerVueOrienteeParAngles swApp, swAssy, swDraw, swMathUtil, 45#, ANGLE_ISO, \"GEN_IsoHG\"\n    Set swView = CreerVueAvecDiagnostic(swDraw, assyPath, \"GEN_IsoHG\", 0.12, 0.16, errTxt)\n    echelleDiag = AjusterEchelleVue(swView, largeurZone2, HAUTEUR_ZONE_VUES)\n    If InStr(1, echelleDiag, \"err\", vbTextCompare) > 0 Then rapport = rapport & \"    [Echelle KO] \" & echelleDiag & vbCrLf\n    PositionnerCoinHautGauche swView, MARGE_CARTOUCHE, HAUTEUR_FEUILLE - MARGE_CARTOUCHE\n    If Not swView Is Nothing Then swVues001.Add swView\n    rapport = rapport & \"Vue Iso haut-gauche (001) : \" & ResultatTxt(swView, errTxt) & vbCrLf\n\n    ' Position de la 2e vue calculee dynamiquement a partir de l'emprise REELLE\n    ' de la 1ere (IView.GetOutline, apres son propre ajustement d'echelle),\n    ' au lieu d'une coordonnee X fixe devinee.\n    Dim xIsoHD As Double\n    xIsoHD = BordDroit(swView, 0.3) + MARGE_VUE\n\n    CreerVueOrienteeParAngles swApp, swAssy, swDraw, swMathUtil, -45#, ANGLE_ISO, \"GEN_IsoHD\"\n    Set swView = CreerVueAvecDiagnostic(swDraw, assyPath, \"GEN_IsoHD\", xIsoHD, 0.16, errTxt)\n    echelleDiag = AjusterEchelleVue(swView, largeurZone2, HAUTEUR_ZONE_VUES)\n    If InStr(1, echelleDiag, \"err\", vbTextCompare) > 0 Then rapport = rapport & \"    [Echelle KO] \" & echelleDiag & vbCrLf\n    PositionnerCoinHautGauche swView, xIsoHD, HAUTEUR_FEUILLE - MARGE_CARTOUCHE\n    If Not swView Is Nothing Then swVues001.Add swView\n    rapport = rapport & \"Vue Iso haut-droite (001) : \" & ResultatTxt(swView, errTxt) & vbCrLf\n\n    ' Centrage du groupe (les 2 vues ISO ensemble, espacement entre elles\n    ' preserve) dans la zone utile de la feuille - cf. CentrerVues, ajoute\n    ' le 2026-10-12 pour eviter que tout le \"mou\" du redimensionnement\n    ' s'accumule en bas/a droite (feuille visiblement desequilibree sinon).\n    CentrerVues swVues001, MARGE_CARTOUCHE, LARGEUR_FEUILLE - MARGE_CARTOUCHE, _\n                HAUTEUR_FEUILLE - MARGE_CARTOUCHE - HAUTEUR_ZONE_VUES, HAUTEUR_FEUILLE - MARGE_CARTOUCHE\n\n    ' --- 3. Feuille 002 : vue de face (Y=0,X=0 - c'est la base) + vue de cote (Y=-90) ---\n    If Not swDraw.ActivateSheet(\"002\") Then\n        MsgBox \"Feuille '002' introuvable dans le gabarit.\", vbCritical\n        Exit Sub\n    End If\n\n    Dim swVues002 As New Collection\n\n    CreerVueOrienteeParAngles swApp, swAssy, swDraw, swMathUtil, 0#, 0#, \"GEN_Face\"\n    Set swView = CreerVueAvecDiagnostic(swDraw, assyPath, \"GEN_Face\", 0.1, 0.2, errTxt)\n    echelleDiag = AjusterEchelleVue(swView, largeurZone2, HAUTEUR_ZONE_VUES)\n    If InStr(1, echelleDiag, \"err\", vbTextCompare) > 0 Then rapport = rapport & \"    [Echelle KO] \" & echelleDiag & vbCrLf\n    PositionnerCoinHautGauche swView, MARGE_CARTOUCHE, HAUTEUR_FEUILLE - MARGE_CARTOUCHE\n    If Not swView Is Nothing Then swVues002.Add swView\n    rapport = rapport & \"Vue de face (002) : \" & ResultatTxt(swView, errTxt) & vbCrLf\n\n    Dim xCote As Double\n    xCote = BordDroit(swView, 0.3) + MARGE_VUE\n\n    CreerVueOrienteeParAngles swApp, swAssy, swDraw, swMathUtil, -90#, 0#, \"GEN_Cote\"\n    Set swView = CreerVueAvecDiagnostic(swDraw, assyPath, \"GEN_Cote\", xCote, 0.2, errTxt)\n    echelleDiag = AjusterEchelleVue(swView, largeurZone2, HAUTEUR_ZONE_VUES)\n    If InStr(1, echelleDiag, \"err\", vbTextCompare) > 0 Then rapport = rapport & \"    [Echelle KO] \" & echelleDiag & vbCrLf\n    PositionnerCoinHautGauche swView, xCote, HAUTEUR_FEUILLE - MARGE_CARTOUCHE\n    If Not swView Is Nothing Then swVues002.Add swView\n    rapport = rapport & \"Vue de cote (002) : \" & ResultatTxt(swView, errTxt) & vbCrLf\n\n    CentrerVues swVues002, MARGE_CARTOUCHE, LARGEUR_FEUILLE - MARGE_CARTOUCHE, _\n                HAUTEUR_FEUILLE - MARGE_CARTOUCHE - HAUTEUR_ZONE_VUES, HAUTEUR_FEUILLE - MARGE_CARTOUCHE\n\n    ' --- 4. Feuille 003 : 1 vue ISO - reutilise GEN_IsoHG deja creee (feuille 001), pas de recalcul ---\n    ' (l'orientation nommee est reutilisee, mais c'est une nouvelle instance de\n    ' vue sur cette feuille - echelle/position lui sont propres, a traiter a part)\n    If Not swDraw.ActivateSheet(\"003\") Then\n        MsgBox \"Feuille '003' introuvable dans le gabarit.\", vbCritical\n        Exit Sub\n    End If\n\n    Set swView = CreerVueAvecDiagnostic(swDraw, assyPath, \"GEN_IsoHG\", 0.2, 0.16, errTxt)\n    echelleDiag = AjusterEchelleVue(swView, LARGEUR_FEUILLE - 2# * MARGE_CARTOUCHE, HAUTEUR_ZONE_VUES)\n    If InStr(1, echelleDiag, \"err\", vbTextCompare) > 0 Then rapport = rapport & \"    [Echelle KO] \" & echelleDiag & vbCrLf\n    PositionnerCoinHautGauche swView, MARGE_CARTOUCHE, HAUTEUR_FEUILLE - MARGE_CARTOUCHE\n    rapport = rapport & \"Vue ISO (003) : \" & ResultatTxt(swView, errTxt) & vbCrLf\n\n    If Not swView Is Nothing Then\n        Dim swVues003 As New Collection\n        swVues003.Add swView\n        CentrerVues swVues003, MARGE_CARTOUCHE, LARGEUR_FEUILLE - MARGE_CARTOUCHE, _\n                    HAUTEUR_FEUILLE - MARGE_CARTOUCHE - HAUTEUR_ZONE_VUES, HAUTEUR_FEUILLE - MARGE_CARTOUCHE\n    End If\n\n    Dim couleurDiag As String\n    couleurDiag = ColorerUnitsFeuille003(swDraw, swView)\n    rapport = rapport & \"Coloration Units (003) : \" & couleurDiag & vbCrLf\n\n    ' --- 5. PHASE 2 (premier jet) : une feuille + 1 vue ISO par Unit de premier niveau ---\n    ' Regles de detection reprises de DetecterUnits.bas/CLAUDE.md (\"Distinction\n    ' Unit vs accessoire\"). NON TESTE : ActivateDoc2 sur le document d'une Unit\n    ' chargee uniquement comme composant reference (jamais ouverte separement) -\n    ' si ca echoue, c'est le premier point a diagnostiquer (voir rapport).\n    Dim vComps As Variant\n    vComps = swAssy.GetComponents(True) ' True = premier niveau uniquement\n\n    ' MAJ 2026-10-12 : compte TOUJOURS le nombre de composants premier niveau\n    ' trouves (avant tout filtre Unit) - si ce chiffre est 0, le probleme est\n    ' en amont (vComps/swAssy), pas dans les regles de filtrage Unit\n    ' ci-dessous. Permet de distinguer \"0 composant premier niveau du tout\"\n    ' de \"des composants existent mais aucun ne passe le filtre Unit\".\n    Dim nbCompPremierNiveau As Long\n    nbCompPremierNiveau = 0\n    If Not IsEmpty(vComps) Then nbCompPremierNiveau = UBound(vComps) - LBound(vComps) + 1\n    rapport = rapport & vbCrLf & \"Composants premier niveau trouves sur l'assemblage : \" & nbCompPremierNiveau & vbCrLf\n\n    Dim unitIndex As Long\n    unitIndex = 0\n    Dim nbUnitsTraitees As Long\n    nbUnitsTraitees = 0\n    Dim nomsFeuillesUnit As New Collection ' pour le reordonnancement final (Info en dernier)\n\n    If Not IsEmpty(vComps) Then\n        Dim iComp As Long\n        For iComp = 0 To UBound(vComps)\n            Dim swComp As SldWorks.Component2\n            Set swComp = vComps(iComp)\n\n            On Error Resume Next\n            Dim compPath As String\n            compPath = swComp.GetPathName\n            Dim estSupprime As Boolean\n            estSupprime = (swComp.GetSuppression2 = 4) ' 4 = swComponentSuppressed\n            On Error GoTo 0\n\n            Dim estSldasm As Boolean, estBibliotheque As Boolean, estMannequin As Boolean, estDecoratif As Boolean\n            estSldasm = (LCase(Right(compPath, 7)) Like \"*.sldasm\")\n            estBibliotheque = (LCase(Left(compPath, 2)) = \"x:\") ' lecteur de la bibliotheque [caviardé]\n            estMannequin = (InStr(1, compPath, \"Mannequin\", vbTextCompare) > 0)\n            estDecoratif = (InStr(1, compPath, \"Pour mise en plan\", vbTextCompare) > 0)\n\n            If Not estSupprime And estSldasm And Not estBibliotheque And Not estMannequin And Not estDecoratif Then\n\n                Dim swUnitDoc As SldWorks.ModelDoc2\n                Set swUnitDoc = swComp.GetModelDoc2\n\n                Dim labelUnit As String\n                labelUnit = ObtenirLabelUnit(swComp)\n\n                ' Numerotation par bloc de 10 par Unit (010/011/012.../020/021...) -\n                ' laisse la place a d'autres feuilles par Unit plus tard (vues\n                ' orthogonales cotees, etc. - standard complet, cf. CLAUDE.md).\n                ' Pour l'instant une seule feuille par Unit = le 1er numero du bloc.\n                unitIndex = unitIndex + 1\n                Dim nomFeuilleUnit As String\n                nomFeuilleUnit = Format(unitIndex * 10, \"000\")\n\n                rapport = rapport & vbCrLf & \"--- Unit : \" & nomFeuilleUnit & \" (\" & labelUnit & \") ---\" & vbCrLf\n\n                On Error Resume Next\n                Err.Clear\n                Dim sheetOk As Boolean\n                sheetOk = swDraw.NewSheet3(nomFeuilleUnit, 12, 12, 1#, 10#, True, NOM_FORMAT_FEUILLE, LARGEUR_FEUILLE, HAUTEUR_FEUILLE, \"Par défaut\")\n                Dim sheetErr As String\n                sheetErr = \"\"\n                If Err.Number <> 0 Then sheetErr = \" [err NewSheet3 \" & Err.Number & \" \" & Err.Description & \"]\"\n                On Error GoTo 0\n                rapport = rapport & \"NewSheet3=\" & sheetOk & sheetErr & vbCrLf\n\n                If sheetOk And Not swUnitDoc Is Nothing Then\n                    nbUnitsTraitees = nbUnitsTraitees + 1\n                    nomsFeuillesUnit.Add nomFeuilleUnit\n\n                    swDraw.ActivateSheet nomFeuilleUnit\n\n                    Dim unitPath As String\n                    unitPath = swUnitDoc.GetPathName\n\n                    ' Zone cible de la vue ISO : largeur utile de la feuille MOINS la\n                    ' bande reservee a la nomenclature en haut-droite (evite qu'un gros\n                    ' assemblage mis a l'echelle max chevauche la nomenclature).\n                    Dim largeurZoneIsoUnit As Double\n                    largeurZoneIsoUnit = LARGEUR_FEUILLE - 2# * MARGE_CARTOUCHE - LARGEUR_ZONE_NOMENCLATURE - MARGE_VUE\n\n                    CreerVueOrienteeParAngles swApp, swUnitDoc, swDraw, swMathUtil, 45#, ANGLE_ISO, \"GEN_IsoHG\"\n                    Set swView = CreerVueAvecDiagnostic(swDraw, unitPath, \"GEN_IsoHG\", 0.2, 0.16, errTxt)\n                    echelleDiag = AjusterEchelleVue(swView, largeurZoneIsoUnit, HAUTEUR_ZONE_VUES)\n                    If InStr(1, echelleDiag, \"err\", vbTextCompare) > 0 Then rapport = rapport & \"    [Echelle KO] \" & echelleDiag & vbCrLf\n                    PositionnerCoinHautGauche swView, MARGE_CARTOUCHE, HAUTEUR_FEUILLE - MARGE_CARTOUCHE_UNIT\n                    rapport = rapport & \"Vue ISO Unit : \" & ResultatTxt(swView, errTxt) & vbCrLf\n\n                    If Not swView Is Nothing Then\n                        ' Convention : nomenclature accrochee par son coin HAUT-DROIT,\n                        ' plaquee dans le coin haut-droit UTILE de la feuille\n                        ' (MARGE_CARTOUCHE, pas le bord papier brut) - position fixe\n                        ' independante de la vue ISO, PAS a cote d'elle.\n                        Dim xNomenclature As Double, yNomenclature As Double\n                        xNomenclature = LARGEUR_FEUILLE - MARGE_CARTOUCHE\n                        yNomenclature = HAUTEUR_FEUILLE - MARGE_CARTOUCHE\n                        rapport = rapport & \"Nomenclature Unit : \" & InsererNomenclatureUnit(swDraw, swView, CHEMIN_GABARIT_NOMENCLATURE, xNomenclature, yNomenclature) & vbCrLf\n                    End If\n\n                    ' --- Feuille de cotation de l'Unit (0N1) : Face + Cote + Dessus,\n                    ' meme mecanisme que la feuille 002 (racine), applique a la Unit.\n                    ' Dessus = X+90 (PAS -90 comme indique dans le document source -\n                    ' meme inversion de signe deja constatee et corrigee pour l'ISO,\n                    ' cf. en-tete de fichier) - HYPOTHESE, a verifier visuellement.\n                    Dim nomFeuilleCotation As String\n                    nomFeuilleCotation = Format(unitIndex * 10 + 1, \"000\")\n\n                    On Error Resume Next\n                    Err.Clear\n                    Dim sheetCotationOk As Boolean\n                    sheetCotationOk = swDraw.NewSheet3(nomFeuilleCotation, 12, 12, 1#, 10#, True, NOM_FORMAT_FEUILLE, LARGEUR_FEUILLE, HAUTEUR_FEUILLE, \"Par défaut\")\n                    Dim sheetCotationErr As String\n                    sheetCotationErr = \"\"\n                    If Err.Number <> 0 Then sheetCotationErr = \" [err NewSheet3 \" & Err.Number & \" \" & Err.Description & \"]\"\n                    On Error GoTo 0\n                    rapport = rapport & \"NewSheet3(\" & nomFeuilleCotation & \")=\" & sheetCotationOk & sheetCotationErr & vbCrLf\n\n                    If sheetCotationOk Then\n                        nomsFeuillesUnit.Add nomFeuilleCotation\n                        swDraw.ActivateSheet nomFeuilleCotation\n\n                        ' Face et Dessus se partagent la moitie haute/basse de la zone de\n                        ' vues (Dessus est sous Face) ; Cote occupe la meme bande haute que\n                        ' Face, a sa droite - meme largeurZone2 que la feuille 002 racine.\n                        Dim hauteurZoneDemieUnit As Double\n                        hauteurZoneDemieUnit = HAUTEUR_ZONE_VUES / 2#\n\n                        CreerVueOrienteeParAngles swApp, swUnitDoc, swDraw, swMathUtil, 0#, 0#, \"GEN_Face\"\n                        Set swView = CreerVueAvecDiagnostic(swDraw, unitPath, \"GEN_Face\", 0.1, 0.2, errTxt)\n                        echelleDiag = AjusterEchelleVue(swView, largeurZone2, hauteurZoneDemieUnit)\n                        If InStr(1, echelleDiag, \"err\", vbTextCompare) > 0 Then rapport = rapport & \"    [Echelle KO] \" & echelleDiag & vbCrLf\n                        PositionnerCoinHautGauche swView, MARGE_CARTOUCHE, HAUTEUR_FEUILLE - MARGE_CARTOUCHE_UNIT\n                        rapport = rapport & \"Vue de face Unit : \" & ResultatTxt(swView, errTxt) & vbCrLf\n\n                        ' Cote a droite de Face (meme calcul que la feuille 002 racine, le\n                        ' chainage sur l'emprise REELLE de Face est correct ici : 2 vues\n                        ' cote a cote doivent se coller l'une a l'autre, pas a une colonne\n                        ' fixe). Dessus est une vue SEULE sur toute la largeur de la ligne\n                        ' du dessous - donc PAS chainee sur l'emprise de Face : si Face\n                        ' (piece tres allongee, vue bout-a-bout le long de Réf Longueur)\n                        ' rend petite, un yDessusUnit chaine sur son BordBas remontait\n                        ' la ligne 2 bien plus haut que prevu (chevauchement/regroupement\n                        ' constate visuellement le 2026-10-12 sur Unit B, tres allongee -\n                        ' Face minuscule, Dessus \"remonte\" juste sous elle au lieu d'occuper\n                        ' toute la bande du bas). Fix : yDessusUnit ancre sur la frontiere\n                        ' FIXE entre les 2 lignes (bas de la ligne du haut), independante de\n                        ' la taille reelle de Face.\n                        Dim xCoteUnit As Double, yDessusUnit As Double\n                        xCoteUnit = BordDroit(swView, 0.3) + MARGE_VUE\n                        yDessusUnit = (HAUTEUR_FEUILLE - MARGE_CARTOUCHE_UNIT - hauteurZoneDemieUnit) - MARGE_VUE\n\n                        CreerVueOrienteeParAngles swApp, swUnitDoc, swDraw, swMathUtil, -90#, 0#, \"GEN_Cote\"\n                        Set swView = CreerVueAvecDiagnostic(swDraw, unitPath, \"GEN_Cote\", xCoteUnit, 0.2, errTxt)\n                        echelleDiag = AjusterEchelleVue(swView, largeurZone2, hauteurZoneDemieUnit)\n                        If InStr(1, echelleDiag, \"err\", vbTextCompare) > 0 Then rapport = rapport & \"    [Echelle KO] \" & echelleDiag & vbCrLf\n                        PositionnerCoinHautGauche swView, xCoteUnit, HAUTEUR_FEUILLE - MARGE_CARTOUCHE_UNIT\n                        rapport = rapport & \"Vue de cote Unit : \" & ResultatTxt(swView, errTxt) & vbCrLf\n\n                        ' Dessus seule sur sa ligne : lui donner toute la largeur utile de\n                        ' la feuille (pas largeurZone2, pensee pour 2 vues cote a cote) -\n                        ' utilise mieux l'espace au lieu de rester cantonnee a la colonne de\n                        ' Face avec la colonne de Cote vide en dessous (meme symptome\n                        ' \"regroupe dans un coin\" constate visuellement).\n                        Dim largeurZonePleine As Double\n                        largeurZonePleine = LARGEUR_FEUILLE - 2# * MARGE_CARTOUCHE\n\n                        CreerVueOrienteeParAngles swApp, swUnitDoc, swDraw, swMathUtil, 0#, 90#, \"GEN_Dessus\"\n                        Set swView = CreerVueAvecDiagnostic(swDraw, unitPath, \"GEN_Dessus\", 0.1, yDessusUnit, errTxt)\n                        echelleDiag = AjusterEchelleVue(swView, largeurZonePleine, hauteurZoneDemieUnit)\n                        If InStr(1, echelleDiag, \"err\", vbTextCompare) > 0 Then rapport = rapport & \"    [Echelle KO] \" & echelleDiag & vbCrLf\n                        PositionnerCoinHautGauche swView, MARGE_CARTOUCHE, yDessusUnit\n                        rapport = rapport & \"Vue de dessus Unit : \" & ResultatTxt(swView, errTxt) & vbCrLf\n                    End If\n                ElseIf swUnitDoc Is Nothing Then\n                    rapport = rapport & \"ECHEC (composant Unit non resolu/charge, GetModelDoc2=Nothing) - vue ignoree\" & vbCrLf\n                End If\n\n            End If\n        Next iComp\n    End If\n\n    ' --- 6. Reordonner les feuilles : 001/002/003, puis les Unit dans l'ordre\n    ' de creation, puis Gamme/Info en dernier (elles se retrouvent sinon\n    ' coincees juste apres 003 - leur position native dans le gabarit - au\n    ' lieu de passer en fin apres les nouvelles feuilles Unit, ajoutees par\n    ' NewSheet3 a la fin de l'onglet). MAJ 2026-10-12 : \"Gamme\" (feuille\n    ' native du gabarit de production, en plus d'Info) manquait de ce\n    ' tableau - ReorderSheets semble exiger la liste COMPLETE des feuilles\n    ' du document pour reordonner correctement ; en son absence, Gamme (et\n    ' Info, sa voisine immediate dans le gabarit) restaient coincees entre\n    ' 003 et les feuilles Unit au lieu d'aller en fin (ordre constate :\n    ' 001,002,003,Gamme,Info,010,011,020,021 au lieu de l'ordre voulu\n    ' 001,002,003,010,011,020,021,Gamme,Info). ---\n    On Error Resume Next\n    Dim nomsFeuilles() As String\n    ReDim nomsFeuilles(0 To 4 + nomsFeuillesUnit.Count)\n    nomsFeuilles(0) = \"001\"\n    nomsFeuilles(1) = \"002\"\n    nomsFeuilles(2) = \"003\"\n    Dim iSheet As Long\n    For iSheet = 1 To nomsFeuillesUnit.Count\n        nomsFeuilles(2 + iSheet) = nomsFeuillesUnit(iSheet)\n    Next iSheet\n    nomsFeuilles(3 + nomsFeuillesUnit.Count) = \"Gamme\"\n    nomsFeuilles(4 + nomsFeuillesUnit.Count) = \"Info\"\n\n    ' L'enregistrement d'origine (cf. CLAUDE.md) passait un Variant contenant\n    ' le tableau, pas le tableau String() directement - meme famille de piege\n    ' de marshaling que Array() avec CreatePoint/CreateVector.\n    Dim nomsFeuillesVariant As Variant\n    nomsFeuillesVariant = nomsFeuilles\n\n    Err.Clear\n    Dim reorderOk As Boolean\n    reorderOk = swDraw.ReorderSheets((nomsFeuillesVariant))\n    Dim reorderErr As String\n    reorderErr = \"\"\n    If Err.Number <> 0 Then reorderErr = \" [err \" & Err.Number & \" \" & Err.Description & \"]\"\n    On Error GoTo 0\n\n    Dim listeOrdre As String\n    Dim iListe As Long\n    For iListe = LBound(nomsFeuilles) To UBound(nomsFeuilles)\n        listeOrdre = listeOrdre & nomsFeuilles(iListe) & \" / \"\n    Next iListe\n\n    ' --- 7. Parcours visuel de toutes les feuilles (demande utilisateur,\n    ' generation filmee pour une video de demonstration) : purement cosmetique,\n    ' active chaque feuille dans l'ordre final (001 -> ... -> Gamme -> Info)\n    ' avec une pause breve entre deux pour que le defilement soit visible a\n    ' l'ecran, puis revient sur \"001\" (feuille de garde apres generation -\n    ' comportement deja en place avant cet ajout, inchange). Reutilise\n    ' nomsFeuilles deja construit pour ReorderSheets (meme ordre final).\n    On Error Resume Next\n    Dim iParcours As Long\n    For iParcours = LBound(nomsFeuilles) To UBound(nomsFeuilles)\n        swDraw.ActivateSheet nomsFeuilles(iParcours)\n        AttendreBref DELAI_PARCOURS_FEUILLES\n    Next iParcours\n    On Error GoTo 0\n\n    swDraw.ActivateSheet \"001\"\n\n    ' MAJ 2026-10-12 (demande utilisateur, generation filmee pour une video\n    ' de demonstration) : si TOUT s'est bien passe, un seul message COURT et\n    ' propre suffit - plus de boite ReorderSheets intermediaire ni de dump\n    ' technique (diag/[err .../ECHEC) a l'ecran. Le rapport technique\n    ' complet (celui d'avant) reste affiche SI quelque chose a echoue, pour\n    ' ne rien perdre en diagnosticabilite - detection par simple recherche\n    ' de marqueurs d'echec deja presents dans rapport/reorderOk (ECHEC,\n    ' [err, KO] - tous les points d'echec du fichier utilisent deja l'un de\n    ' ces 3 marqueurs, cf. ResultatTxt/AjusterEchelleVue/etc. ci-dessous).\n    ' MAJ 2026-10-12 : \"0 Unit traitee\" doit faire basculer sur le rapport\n    ' detaille, meme sans erreur VBA - sinon la boucle Phase 2 peut etre\n    ' entierement sautee (vComps vide, ou aucun composant ne passe le\n    ' filtre Unit) sans que ca se voie, puisqu'aucune ligne ECHEC/[err/KO]\n    ' n'est generee dans ce cas (rien ne s'execute, donc rien n'echoue).\n    Dim toutOk As Boolean\n    toutOk = reorderOk And reorderErr = \"\" And _\n             nbUnitsTraitees > 0 And _\n             InStr(1, rapport, \"ECHEC\", vbTextCompare) = 0 And _\n             InStr(1, rapport, \"[err\", vbTextCompare) = 0 And _\n             InStr(1, rapport, \"KO]\", vbTextCompare) = 0\n\n    If toutOk Then\n        MsgBox \"Mise en plan generee avec succes !\" & vbCrLf & vbCrLf & _\n               \"(\" & nbUnitsTraitees & \" Unit traitee(s))\" & vbCrLf & vbCrLf & _\n               \"RAPPEL : pour les Unit contenant des profiles/pieces soudees, cocher\" & vbCrLf & _\n               \"MANUELLEMENT 'Liste detaillee des pieces soudees' dans les Proprietes\" & vbCrLf & _\n               \"de leur nomenclature.\", vbInformation\n    Else\n        MsgBox \"ReorderSheets (Gamme/Info en dernier) : \" & reorderOk & reorderErr & vbCrLf & vbCrLf & _\n               \"Ordre demande : \" & listeOrdre, vbInformation\n\n        MsgBox \"Resultat de la generation (anomalie(s) detectee(s) ci-dessous) :\" & vbCrLf & vbCrLf & rapport & vbCrLf & _\n               \"Verifiez visuellement l'orientation (feuille 001 : 2 cotes differents du modele, meme inclinaison ISO ;\" & vbCrLf & _\n               \"feuille 002 : face/cote corrects) et le positionnement des vues.\" & vbCrLf & vbCrLf & _\n               \"RAPPEL : pour les Unit contenant des profiles/pieces soudees, cocher MANUELLEMENT\" & vbCrLf & _\n               \"'Liste detaillee des pieces soudees' dans les Proprietes de leur nomenclature\" & vbCrLf & _\n               \"(reglage non pilotable par API - voir CLAUDE.md).\", vbInformation\n    End If\n\nEnd Sub\n\n'-------------------------------------------------------------------------\n' Label d'une Unit = propriete personnalisee \"Désignation Secondaire\" (a la\n' config referencee, PAS Default), repli sur le nom du composant si absente -\n' meme logique que DetecterUnits.bas, cf. CLAUDE.md \"Label de sous-ensemble\".\n'-------------------------------------------------------------------------\nPrivate Function ObtenirLabelUnit(swComp As SldWorks.Component2) As String\n\n    On Error Resume Next\n\n    Dim compName As String, refConfig As String\n    compName = swComp.Name2\n    refConfig = swComp.ReferencedConfiguration\n\n    Dim designationSecondaire As String\n    designationSecondaire = \"\"\n\n    Dim modelDoc As Object\n    Set modelDoc = swComp.GetModelDoc2\n    If Not modelDoc Is Nothing Then\n        Dim swCPM As Object\n        Set swCPM = modelDoc.Extension.CustomPropertyManager(refConfig)\n        If Not swCPM Is Nothing Then\n            Dim valOut As String, resolvedVal As String, wasResolved As Boolean\n            valOut = \"\": resolvedVal = \"\": wasResolved = False\n            swCPM.Get5 \"Désignation Secondaire\", False, valOut, resolvedVal, wasResolved\n            designationSecondaire = resolvedVal\n            If designationSecondaire = \"\" Then\n                valOut = \"\": resolvedVal = \"\": wasResolved = False\n                swCPM.Get5 \"Designation Secondaire\", False, valOut, resolvedVal, wasResolved\n                designationSecondaire = resolvedVal\n            End If\n        End If\n    End If\n\n    If designationSecondaire <> \"\" Then\n        ObtenirLabelUnit = designationSecondaire\n    Else\n        ObtenirLabelUnit = compName\n    End If\n\nEnd Function\n\n'-------------------------------------------------------------------------\n' Enveloppe CreateDrawViewFromModelView3 avec capture d'erreur complete.\n'-------------------------------------------------------------------------\nPrivate Function CreerVueAvecDiagnostic(swDraw As SldWorks.ModelDoc2, modelPath As String, viewName As String, x As Double, y As Double, ByRef errTxt As String) As Object\n\n    Dim swDrawDoc As SldWorks.DrawingDoc\n    Set swDrawDoc = swDraw\n\n    On Error Resume Next\n    Err.Clear\n    Dim v As Object\n    Set v = swDrawDoc.CreateDrawViewFromModelView3(modelPath, viewName, x, y, 0)\n    If Err.Number <> 0 Then\n        errTxt = CStr(Err.Number) & \" - \" & Err.Description\n    Else\n        errTxt = \"\"\n    End If\n    On Error GoTo 0\n\n    Set CreerVueAvecDiagnostic = v\n\nEnd Function\n\nPrivate Function ResultatTxt(v As Object, errTxt As String) As String\n    If Not v Is Nothing Then\n        ResultatTxt = \"OK\"\n    ElseIf errTxt <> \"\" Then\n        ResultatTxt = \"ECHEC (erreur VBA \" & errTxt & \")\"\n    Else\n        ResultatTxt = \"ECHEC (Nothing renvoye, pas d'erreur VBA)\"\n    End If\nEnd Function\n\n'-------------------------------------------------------------------------\n' Insere une nomenclature liee a la vue donnee (deja posee sur la feuille\n' active), avec swBomType_PartsOnly (CORRIGE le 2026-09-21 - meme valeur\n' que DiagnosticPreGeneration.bas, qui l'utilise pour un usage different\n' - descendre jusqu'aux vraies feuilles pour detecter les trous - mais la\n' meme constante convient ici : elle correspond au bouton \"Pieces\n' uniquement\" du dialogue d'insertion manuelle de reference, PAS\n' TopLevelOnly comme suppose au depart). Signature confirmee par enregistrement macro le\n' 2026-09-20 : IDrawingView.InsertBomTable4(CreateNewTable As Boolean,\n' X As Double, Y As Double, ConfigAnchorType As Long, BomType As Long,\n' ConfigurationName As String, TemplateName As String, Boolean, Long,\n' Boolean) - appelee sur la VUE ACTIVE (ActiveDrawingView), PAS sur\n' l'Extension du document comme InsertBomTable3. Il faut d'abord activer la\n' vue par son nom (ActivateView + SelectByID2 + ClearSelection2, ordre exact\n' de l'enregistrement) avant de lire ActiveDrawingView.\n'-------------------------------------------------------------------------\nPrivate Function InsererNomenclatureUnit(swDraw As SldWorks.ModelDoc2, swVue As Object, gabaritNomenclature As String, x As Double, y As Double) As String\n\n    Dim diag As String\n    Dim swDrawDoc As SldWorks.DrawingDoc\n    Set swDrawDoc = swDraw\n\n    On Error Resume Next\n\n    Err.Clear\n    Dim nomVue As String\n    nomVue = swVue.GetName2\n    diag = \"GetName2=\" & nomVue\n    If Err.Number <> 0 Then diag = diag & \" [err GetName2 \" & Err.Number & \" \" & Err.Description & \"]\"\n\n    Err.Clear\n    swDrawDoc.ActivateView nomVue\n    If Err.Number <> 0 Then diag = diag & \" [err ActivateView \" & Err.Number & \" \" & Err.Description & \"]\"\n\n    Err.Clear\n    swDrawDoc.Extension.SelectByID2 nomVue, \"DRAWINGVIEW\", 0, 0, 0, False, 0, Nothing, 0\n    swDrawDoc.ClearSelection2 True\n    If Err.Number <> 0 Then diag = diag & \" [err select vue \" & Err.Number & \" \" & Err.Description & \"]\"\n\n    Err.Clear\n    Dim swActiveView As Object\n    Set swActiveView = swDrawDoc.ActiveDrawingView\n    diag = diag & \", ActiveDrawingView=\" & IIf(swActiveView Is Nothing, \"Nothing\", \"OK\")\n    If Err.Number <> 0 Then diag = diag & \" [err ActiveDrawingView \" & Err.Number & \" \" & Err.Description & \"]\"\n\n    If Not swActiveView Is Nothing Then\n        ' ConfigurationName = \"\" (litteral repris de l'enregistrement) a\n        ' produit une table sans aucune ligne le 2026-09-20 - CLAUDE.md\n        ' interdit deja de supposer une config vide/Default. On passe la\n        ' vraie config affichee par la vue.\n        Err.Clear\n        Dim configVue As String\n        configVue = swVue.ReferencedConfiguration\n        diag = diag & \", ReferencedConfiguration=\" & configVue\n        If Err.Number <> 0 Then diag = diag & \" [err ReferencedConfiguration \" & Err.Number & \" \" & Err.Description & \"]\"\n\n        Err.Clear\n        Dim swBomTable As Object\n        ' InsertBomTable4(UseAnchorPoint, X, Y, AnchorType, BomType, Configuration,\n        ' TableTemplate, Hidden, IndentedNumberingType, DetailedCutList) - signature\n        ' verifiee dans l'Explorateur d'objets. Nomenclature \"pieces uniquement\",\n        ' ancree en haut a droite ; DetailedCutList reste sans effet (voir plus bas).\n        Set swBomTable = swActiveView.InsertBomTable4(True, x, y, _\n            SW_TABLEANCHOR_HAUT_DROIT, _\n            swBomType_e.swBomType_PartsOnly, configVue, gabaritNomenclature, False, 0, True)\n        diag = diag & \", InsertBomTable4=\" & IIf(swBomTable Is Nothing, \"Nothing\", \"OK\")\n        If Err.Number <> 0 Then diag = diag & \" [err InsertBomTable4 \" & Err.Number & \" \" & Err.Description & \"]\"\n\n        ' Ancrage au point d'ancrage FIXE de la feuille (TableAnnotation.\n        ' Anchored/AnchorType, confirme le 2026-09-21 - \"quelques pixels\n        ' d'ecart\" constates avec le seul positionnement X/Y : le point\n        ' d'ancrage designe dans le gabarit de feuille tombe pile au bon\n        ' endroit, plus precis qu'un X/Y calcule via MARGE_CARTOUCHE. Le\n        ' swBOMConfigurationAnchor_TopRight ci-dessus (parametre\n        ' d'InsertBomTable4) est un concept DIFFERENT (coin de la table\n        ' aligne sur X/Y), pas a confondre avec cet ancrage-feuille.\n        If Not swBomTable Is Nothing Then\n            Err.Clear\n            swBomTable.Anchored = True\n            swBomTable.AnchorType = SW_TABLEANCHOR_HAUT_DROIT\n            diag = diag & \", Anchored=True/AnchorType=\" & SW_TABLEANCHOR_HAUT_DROIT\n            If Err.Number <> 0 Then diag = diag & \" [err ancrage \" & Err.Number & \" \" & Err.Description & \"]\"\n\n            ' \"Liste detaillee des pieces soudees\" : non pilotable par l'API dans\n            ' cette version de SolidWorks (parametre, proprietes, enregistrement\n            ' macro et gabarit testes sans succes) - reste a cocher a la main.\n        End If\n    End If\n\n    swDraw.EditRebuild3\n\n    On Error GoTo 0\n\n    InsererNomenclatureUnit = diag\n\nEnd Function\n\n'-------------------------------------------------------------------------\n' Bloc generique : oriente la vue de l'assemblage a un angle EXACT (rotation\n' Y puis X, en degres) relatif a la vue de Face, via IMathUtility/\n' Orientation3, et sauvegarde comme vue nommee. Voir mecanisme + piege\n' Array() en tete de fichier. Reutilisable pour toute vue ISO/oblique sur\n' mesure (Phase 2 : orientations custom par Unit si besoin).\n'-------------------------------------------------------------------------\nPrivate Function CreerVueOrienteeParAngles(swApp As SldWorks.SldWorks, swAssy As SldWorks.ModelDoc2, swDraw As SldWorks.ModelDoc2, swMathUtil As SldWorks.MathUtility, rotYdeg As Double, rotXdeg As Double, nomVue As String) As String\n\n    Dim diag As String\n    Dim actErr As Long\n\n    On Error Resume Next\n\n    Err.Clear\n    swApp.ActivateDoc2 swAssy.GetTitle, False, actErr\n    diag = \"ActivateDoc2(\" & swAssy.GetTitle & \")\"\n    If Err.Number <> 0 Then diag = diag & \" [err activation assy \" & Err.Number & \" \" & Err.Description & \"]\"\n\n    ' Aller en Face de facon fiable (garde-fou Iso + Normal a, cf. OrienterEtNommerVue)\n    swAssy.ShowNamedView2 \"\", SW_VIEW_ISOMETRIC\n    AttendreBref DELAI_ANIMATION\n\n    swAssy.ClearSelection2 True\n    swAssy.Extension.SelectByID2 \"Réf Longueur\", \"PLANE\", 0, 0, 0, False, 0, Nothing, 0\n    swApp.RunCommand SW_COMMAND_NORMAL_TO, \"\"\n    AttendreBref DELAI_ANIMATION\n\n    Err.Clear\n    Dim baseOrient As SldWorks.MathTransform\n    Set baseOrient = swAssy.ActiveView.Orientation3\n    diag = diag & \", base Face OK\"\n    If Err.Number <> 0 Then diag = diag & \" [err lecture base \" & Err.Number & \" \" & Err.Description & \"]\"\n\n    ' IMPORTANT : tableaux Double() explicites, PAS Array() (cf. piege en tete\n    ' de fichier - Array() corrompt silencieusement CreatePoint/CreateVector).\n    Dim ptArr(2) As Double\n    Dim vecYArr(2) As Double, vecXArr(2) As Double\n    vecYArr(0) = 0#: vecYArr(1) = 1#: vecYArr(2) = 0#\n    vecXArr(0) = 1#: vecXArr(1) = 0#: vecXArr(2) = 0#\n\n    Dim pt As SldWorks.MathPoint\n    Dim vecY As SldWorks.MathVector, vecX As SldWorks.MathVector\n    Set pt = swMathUtil.CreatePoint(ptArr)\n    Set vecY = swMathUtil.CreateVector(vecYArr)\n    Set vecX = swMathUtil.CreateVector(vecXArr)\n\n    Err.Clear\n    Dim finalOrient As SldWorks.MathTransform\n    Set finalOrient = baseOrient\n\n    If rotYdeg <> 0 Then\n        Dim rotY As SldWorks.MathTransform\n        Set rotY = swMathUtil.CreateTransformRotateAxis(pt, vecY, rotYdeg * PI / 180#)\n        Set finalOrient = finalOrient.Multiply(rotY)\n    End If\n\n    If rotXdeg <> 0 Then\n        Dim rotX As SldWorks.MathTransform\n        Set rotX = swMathUtil.CreateTransformRotateAxis(pt, vecX, rotXdeg * PI / 180#)\n        Set finalOrient = finalOrient.Multiply(rotX)\n    End If\n\n    diag = diag & \", rotation composee (Y=\" & rotYdeg & \"°, X=\" & rotXdeg & \"°)\"\n    If Err.Number <> 0 Then diag = diag & \" [err composition \" & Err.Number & \" \" & Err.Description & \"]\"\n\n    Err.Clear\n    swAssy.ActiveView.Orientation3 = finalOrient\n    swAssy.GraphicsRedraw2\n    If Err.Number <> 0 Then diag = diag & \" [err Orientation3 \" & Err.Number & \" \" & Err.Description & \"]\"\n\n    AttendreBref DELAI_ANIMATION\n\n    Err.Clear\n    swAssy.NameView nomVue\n    If Err.Number <> 0 Then diag = diag & \" [err NameView \" & Err.Number & \" \" & Err.Description & \"]\"\n\n    Err.Clear\n    swApp.ActivateDoc2 swDraw.GetTitle, False, actErr\n    If Err.Number <> 0 Then diag = diag & \" [err activation plan \" & Err.Number & \" \" & Err.Description & \"]\"\n\n    On Error GoTo 0\n\n    CreerVueOrienteeParAngles = diag\n\nEnd Function\n\n'-------------------------------------------------------------------------\n' Pause active de 'secondes' secondes (DoEvents) - laisse le temps a une\n' animation de transition de vue en cours de se terminer avant de capturer\n' l'orientation (NameView) ou d'appliquer une rotation supplementaire.\n'-------------------------------------------------------------------------\nPrivate Sub AttendreBref(secondes As Single)\n\n    Dim t As Single\n    t = Timer\n    Do While Timer < t + secondes And Timer >= t ' 2e condition : evite un blocage si Timer boucle a minuit\n        DoEvents\n    Loop\n\nEnd Sub\n\n'-------------------------------------------------------------------------\n' IView.GetOutline retourne l'emprise reelle d'une vue/table deja posee sur\n' la feuille (Xmin, Ymin, Xmax, Ymax, en metres, coord feuille) - permet de\n' positionner l'element suivant dynamiquement au lieu de coordonnees fixes\n' devinees. Repli sur la valeur donnee si l'appel echoue (vue Nothing,\n' GetOutline indisponible sur ce type d'objet...).\n'-------------------------------------------------------------------------\nPrivate Function BordDroit(swObjet As Object, repli As Double) As Double\n\n    On Error Resume Next\n    BordDroit = repli\n    If swObjet Is Nothing Then Exit Function\n\n    Dim emprise As Variant\n    emprise = swObjet.GetOutline\n    If Err.Number = 0 And Not IsEmpty(emprise) Then BordDroit = emprise(2)\n    On Error GoTo 0\n\nEnd Function\n\nPrivate Function BordBas(swObjet As Object, repli As Double) As Double\n\n    On Error Resume Next\n    BordBas = repli\n    If swObjet Is Nothing Then Exit Function\n\n    Dim emprise As Variant\n    emprise = swObjet.GetOutline\n    If Err.Number = 0 And Not IsEmpty(emprise) Then BordBas = emprise(1)\n    On Error GoTo 0\n\nEnd Function\n\nPrivate Function Min2(a As Double, b As Double) As Double\n    If a < b Then Min2 = a Else Min2 = b\nEnd Function\n\n'-------------------------------------------------------------------------\n' Ajuste l'echelle d'une vue pour que son encombrement REEL (IView.GetOutline,\n' pas la taille \"nominale\" a l'echelle feuille) tienne dans une zone cible\n' largeurCible x hauteurCible (metres), sans la deformer (meme facteur sur\n' les 2 dimensions, le plus contraignant des deux). Zoom auto qui s'adapte a\n' la taille reelle de chaque assemblage/Unit, remplace une echelle fixe\n' devinee - repond au besoin \"lisible a l'oeil sans surcharger le A3\" pour\n' des assemblages de tailles tres variables.\n' Tolerance 8% : ne rapetisse/agrandit pas une vue deja a peu pres a la\n' bonne taille (evite un aller-retour d'arrondis inutile).\n' IView.ScaleDecimal (Double, ratio decimal DIRECT de l'echelle - ex. 0.05\n' pour 1:20, PAS un tableau numerateur/denominateur comme suppose au depart)\n' et IView.UseSheetScale (Long, cf. piege en tete de fichier) : confirmes le\n' 2026-09-20 via l'Explorateur d'objets.\n'-------------------------------------------------------------------------\nPrivate Function AjusterEchelleVue(swVue As Object, largeurCible As Double, hauteurCible As Double) As String\n\n    Dim diag As String\n\n    On Error Resume Next\n\n    If swVue Is Nothing Then\n        AjusterEchelleVue = \"vue Nothing, echelle inchangee\"\n        Exit Function\n    End If\n\n    Dim emprise As Variant\n    emprise = swVue.GetOutline\n    If Err.Number <> 0 Or IsEmpty(emprise) Then\n        AjusterEchelleVue = \"GetOutline echec, echelle inchangee\"\n        Exit Function\n    End If\n\n    Dim largeurActuelle As Double, hauteurActuelle As Double\n    largeurActuelle = emprise(2) - emprise(0)\n    hauteurActuelle = emprise(3) - emprise(1)\n\n    If largeurActuelle <= 0 Or hauteurActuelle <= 0 Then\n        AjusterEchelleVue = \"encombrement nul, echelle inchangee\"\n        Exit Function\n    End If\n\n    Dim facteur As Double\n    facteur = Min2(largeurCible / largeurActuelle, hauteurCible / hauteurActuelle)\n\n    If facteur > 0.92 And facteur < 1.08 Then\n        AjusterEchelleVue = \"deja a la bonne taille (facteur \" & Format(facteur, \"0.00\") & \"), inchangee\"\n        Exit Function\n    End If\n\n    Err.Clear\n    Dim echelleActuelle As Double\n    echelleActuelle = swVue.ScaleDecimal\n    diag = \"ScaleDecimal lu=\" & Format(echelleActuelle, \"0.0000\")\n    If Err.Number <> 0 Or echelleActuelle <= 0 Then\n        diag = diag & \" [err/nulle - echelle inchangee]\"\n        AjusterEchelleVue = diag\n        Exit Function\n    End If\n\n    ' Property ScaleDecimal As Double (classe View) - confirme le 2026-09-20\n    ' via l'Explorateur d'objets : c'est le ratio decimal DIRECT de l'echelle\n    ' (ex. 0.05 pour une echelle 1:20), PAS un tableau numerateur/denominateur\n    ' comme suppose au depart (1ere hypothese, invalidee - voir piege ci-dessous\n    ' et dans l'entete de fichier). Nouvelle echelle = simple produit.\n    Dim nouvelleEchelle As Double\n    nouvelleEchelle = echelleActuelle * facteur\n\n    ' Une vue nouvellement creee suit par defaut l'echelle de la FEUILLE\n    ' (case \"Utiliser l'echelle de feuille\" cochee dans ses Proprietes) -\n    ' ecrire ScaleDecimal seul est alors sans effet visuel (valeur ecrite\n    ' mais ignoree tant que la case reste cochee). Confirme le 2026-09-20 :\n    ' 1er test visuel montrait des vues inchangees malgre ce code. Il faut\n    ' decocher cette case avant d'ecrire l'echelle personnalisee.\n    ' Property UseSheetScale As Long (classe View) - confirme le 2026-09-20\n    ' via l'Explorateur d'objets. Long, pas Boolean, mais sans consequence\n    ' ici : VBA convertit automatiquement False/True en 0/-1 lors de\n    ' l'affectation a une propriete Long.\n    Err.Clear\n    swVue.UseSheetScale = False\n    diag = diag & \", UseSheetScale=False\"\n    If Err.Number <> 0 Then diag = diag & \" [err UseSheetScale \" & Err.Number & \" \" & Err.Description & \"]\"\n\n    Err.Clear\n    swVue.ScaleDecimal = nouvelleEchelle\n    diag = diag & \", facteur=\" & Format(facteur, \"0.00\") & \", nouvelle echelle=\" & Format(nouvelleEchelle, \"0.0000\")\n    If Err.Number <> 0 Then diag = diag & \" [err ecriture ScaleDecimal \" & Err.Number & \" \" & Err.Description & \"]\"\n\n    On Error GoTo 0\n\n    AjusterEchelleVue = diag\n\nEnd Function\n\n'-------------------------------------------------------------------------\n' Deplace une vue pour que le coin HAUT-GAUCHE de son emprise reelle\n' (IView.GetOutline) tombe exactement sur (xVoulu, yVoulu) - necessaire\n' apres AjusterEchelleVue : une vue grandit/retrecit autour de son point\n' d'ancrage interne (pas depuis son coin), donc changer son echelle deplace\n' son coin haut-gauche ailleurs que la ou CreateDrawViewFromModelView3\n' l'avait pose au depart. Translation rigide : le delta calcule sur\n' l'emprise s'applique tel quel a IView.Position, quelle que soit la\n' semantique exacte de ce point d'ancrage.\n' NON VERIFIE : IView.Position (tableau de 2 Double, X/Y feuille du point\n' d'ancrage de la vue, lisible ET modifiable) - meme statut que ScaleDecimal\n' ci-dessus, a confirmer par Explorateur d'objets si erreur au 1er lancement.\n'-------------------------------------------------------------------------\nPrivate Sub PositionnerCoinHautGauche(swVue As Object, xVoulu As Double, yVoulu As Double)\n\n    On Error Resume Next\n    If swVue Is Nothing Then Exit Sub\n\n    Dim emprise As Variant\n    emprise = swVue.GetOutline\n    If Err.Number <> 0 Or IsEmpty(emprise) Then Exit Sub\n\n    Dim posActuelle As Variant\n    posActuelle = swVue.Position\n    If Err.Number <> 0 Or IsEmpty(posActuelle) Then Exit Sub\n\n    Dim dx As Double, dy As Double\n    dx = xVoulu - emprise(0)        ' emprise(0) = Xmin = coin gauche\n    dy = yVoulu - emprise(3)        ' emprise(3) = Ymax = coin haut\n\n    Dim nouvellePos(1) As Double\n    nouvellePos(0) = posActuelle(0) + dx\n    nouvellePos(1) = posActuelle(1) + dy\n    swVue.Position = nouvellePos\n\n    On Error GoTo 0\n\nEnd Sub\n\n'-------------------------------------------------------------------------\n' Centre un GROUPE de vues (deja scalees/positionnees en haut-gauche de leur\n' zone via PositionnerCoinHautGauche) a l'interieur d'une zone cible\n' [zoneXMin;zoneXMax] x [zoneYMin;zoneYMax] - translation RIGIDE commune a\n' toutes les vues du groupe (calculee sur leur emprise UNION), donc leur\n' espacement relatif entre elles est preserve, seul le bloc entier se\n' deplace. Ajoute le 2026-10-12 (demande utilisateur) : les feuilles\n' 001/002/003 restaient plaquees en haut-gauche de leur zone, laissant tout\n' le \"mou\" du redimensionnement (une vue ne remplit quasi jamais exactement\n' sa zone cible, cf. AjusterEchelleVue) s'accumuler en bas/a droite au lieu\n' d'etre reparti - resultat visuellement desequilibre sur une feuille A3\n' largement vide en bas.\n'-------------------------------------------------------------------------\nPrivate Sub CentrerVues(swVues As Collection, zoneXMin As Double, zoneXMax As Double, zoneYMin As Double, zoneYMax As Double)\n\n    On Error Resume Next\n\n    Dim xMinTotal As Double, yMinTotal As Double, xMaxTotal As Double, yMaxTotal As Double\n    Dim premiere As Boolean\n    premiere = True\n\n    Dim swV As Object\n    For Each swV In swVues\n        If Not swV Is Nothing Then\n            Err.Clear\n            Dim emp As Variant\n            emp = swV.GetOutline\n            If Err.Number = 0 And Not IsEmpty(emp) Then\n                If premiere Then\n                    xMinTotal = emp(0): yMinTotal = emp(1)\n                    xMaxTotal = emp(2): yMaxTotal = emp(3)\n                    premiere = False\n                Else\n                    If emp(0) < xMinTotal Then xMinTotal = emp(0)\n                    If emp(1) < yMinTotal Then yMinTotal = emp(1)\n                    If emp(2) > xMaxTotal Then xMaxTotal = emp(2)\n                    If emp(3) > yMaxTotal Then yMaxTotal = emp(3)\n                End If\n            End If\n        End If\n    Next swV\n\n    If premiere Then Exit Sub ' aucune vue exploitable dans le groupe\n\n    Dim largeurGroupe As Double, hauteurGroupe As Double\n    largeurGroupe = xMaxTotal - xMinTotal\n    hauteurGroupe = yMaxTotal - yMinTotal\n\n    ' Delta commun : decale le coin bas-gauche de l'union du groupe au\n    ' centre de la zone cible, meme si le groupe deborde legerement (delta\n    ' negatif possible, pas de clamp - la zone cible est deja dimensionnee\n    ' par AjusterEchelleVue pour que ca n'arrive normalement pas).\n    Dim dx As Double, dy As Double\n    dx = (zoneXMin + (zoneXMax - zoneXMin - largeurGroupe) / 2#) - xMinTotal\n    dy = (zoneYMin + (zoneYMax - zoneYMin - hauteurGroupe) / 2#) - yMinTotal\n\n    For Each swV In swVues\n        If Not swV Is Nothing Then\n            Err.Clear\n            Dim posActuelleV As Variant\n            posActuelleV = swV.Position\n            If Err.Number = 0 And Not IsEmpty(posActuelleV) Then\n                Dim nouvellePosV(1) As Double\n                nouvellePosV(0) = posActuelleV(0) + dx\n                nouvellePosV(1) = posActuelleV(1) + dy\n                swV.Position = nouvellePosV\n            End If\n        End If\n    Next swV\n\n    On Error GoTo 0\n\nEnd Sub\n\n'-------------------------------------------------------------------------\n' Colore chaque sous-ensemble de 1er niveau visible dans la vue donnee avec\n' un calque distinct (couleur predefinie du gabarit), pour les distinguer\n' visuellement sur la vue ISO d'ensemble (feuille 003). Memes regles de\n' detection \"Unit\" que partout ailleurs dans ce fichier/DetecterUnits.bas\n' (.SLDASM projet, hors bibliotheque de composants standard, hors dossiers decoratifs).\n' Mecanisme confirme le 2026-09-21 (historique complet des tentatives dans\n' SCRIPTS_VBA/EXPLORATION/TestColorationComposant.bas) :\n'   - IView.RootDrawingComponent (le DrawingComponent racine de la vue)\n'     + DrawingComponent.GetChildren (enfants DIRECTS = sous-ensembles de\n'     1er niveau) - PAS IView.GetVisibleComponents, qui aplatit TOUJOURS\n'     aux pieces feuilles et ne renvoie jamais les sous-ensembles eux-memes.\n'   - DrawingComponent.Component renvoie le Component2 sous-jacent (chemin,\n'     Name2... tout ce que DrawingComponent lui-meme n'expose pas).\n'   - DrawingComponent.UseDocumentDefaults = False (decoche \"Utiliser les\n'     reglages par defaut du document\" dans la boite \"Police de ligne du\n'     composant\"), puis DrawingComponent.Select(Append As Boolean,\n'     Data As SelectData) - PAS Select4, specifique a Component2 - puis\n'     DrawingComponent.Layer = \"<nom calque>\". Les \"couleurs predefinies\"\n'     du poste sont en realite des CALQUES nommes dans le gabarit (ex.\n'     \"Rouge vif\", \"Bleu roi\"...), PAS des RVB arbitraires - SetLineColor\n'     (sur DrawingDoc/PartDoc) seul n'a aucun effet tant que le composant\n'     reste sur le calque \"Aucun\".\n'-------------------------------------------------------------------------\nPrivate Function ColorerUnitsFeuille003(swDraw As SldWorks.ModelDoc2, swView As Object) As String\n\n    Dim diag As String\n\n    On Error Resume Next\n\n    Dim swRootDC As Object\n    Set swRootDC = swView.RootDrawingComponent\n    If swRootDC Is Nothing Then\n        ColorerUnitsFeuille003 = \"RootDrawingComponent=Nothing, coloration ignoree\"\n        Exit Function\n    End If\n\n    Dim vChildren As Variant\n    vChildren = swRootDC.GetChildren\n    If IsEmpty(vChildren) Then\n        ColorerUnitsFeuille003 = \"GetChildren vide, coloration ignoree\"\n        Exit Function\n    End If\n\n    Dim unitIndex As Long\n    unitIndex = 0\n\n    Dim i As Long\n    For i = LBound(vChildren) To UBound(vChildren)\n        Dim swChildDC As Object\n        Set swChildDC = vChildren(i)\n\n        Err.Clear\n        Dim swChildComp As Object\n        Set swChildComp = swChildDC.Component\n        If Err.Number = 0 And Not swChildComp Is Nothing Then\n\n            Dim compPath As String\n            compPath = swChildComp.GetPathName\n\n            Dim estSldasm As Boolean, estBibliotheque As Boolean, estMannequin As Boolean, estDecoratif As Boolean\n            estSldasm = (LCase(Right(compPath, 7)) Like \"*.sldasm\")\n            estBibliotheque = (LCase(Left(compPath, 2)) = \"x:\") ' lecteur de la bibliotheque [caviardé]\n            estMannequin = (InStr(1, compPath, \"Mannequin\", vbTextCompare) > 0)\n            estDecoratif = (InStr(1, compPath, \"Pour mise en plan\", vbTextCompare) > 0)\n\n            If estSldasm And Not estBibliotheque And Not estMannequin And Not estDecoratif Then\n                Dim nomCalque As String\n                nomCalque = CouleurUnitParIndex(unitIndex)\n                unitIndex = unitIndex + 1\n\n                Err.Clear\n                swChildDC.UseDocumentDefaults = False\n                swDraw.ClearSelection2 True\n                swChildDC.Select False, Nothing\n                swChildDC.Layer = nomCalque\n                If Err.Number <> 0 Then\n                    diag = diag & \"[err coloration \" & compPath & \" -> \" & nomCalque & \" : \" & Err.Number & \" \" & Err.Description & \"] \"\n                End If\n            End If\n        End If\n    Next i\n\n    On Error GoTo 0\n\n    If diag = \"\" Then diag = unitIndex & \" sous-ensemble(s) colore(s)\"\n\n    ColorerUnitsFeuille003 = diag\n\nEnd Function\n\n'-------------------------------------------------------------------------\n' Calques predefinis du gabarit (menu deroulant \"Calque\" de la boite\n' \"Police de ligne du composant\"), confirmes le 2026-09-21. \"Rouge vif\" et\n' \"Bleu roi\" testes/valides visuellement ; les autres non retestes\n' individuellement mais meme mecanisme (simple nom de calque -> Layer).\n' Cycle si plus de Unit que de couleurs disponibles.\n'-------------------------------------------------------------------------\nPrivate Function CouleurUnitParIndex(index As Long) As String\n    Dim palette As String\n    palette = \"Rouge vif|Bleu roi|Violet|Vert foncé|Orange|Rose|Vert clair|bleu cyan|Rouge pale|Marron\"\n    Dim arr() As String\n    arr = Split(palette, \"|\")\n    CouleurUnitParIndex = arr(index Mod (UBound(arr) - LBound(arr) + 1))\nEnd Function"};
